def solve(inputs: dict) -> float:
    terms = inputs.get('terms', inputs.get('TERMS', inputs.get('a', inputs.get('coefficients'))))
    if terms is None:
        raise ValueError('Expected continued-fraction terms')
    terms = list(terms)
    if not terms:
        raise ValueError('Terms must be nonempty')
    p_prev, p = 1, int(terms[0])
    for a in terms[1:]:
        p_prev, p = p, int(a) * p + p_prev
    return p

